spec.expr:
sum(
  count_over_time(
    {unit="birdnet_analysis.service"}
    | unpack
    | species="$bird"
    | confidence > $threshold
    [1h]
  )
)

sum(
  count_over_time(
    {unit="birdnet_analysis.service"}
    | unpack
    | __error__=""
    | confidence > $threshold
    | species !~ "${exclude_species:pipe}"
    [$__auto]
  )
)

sum by (species) (
  count_over_time(
    {unit="birdnet_analysis.service"}
    | unpack
    | __error__=""
    | confidence > $threshold
    | species !~ "${exclude_species:pipe}"
    [$__auto]
  )
)

sum by () (
  count_over_time(
    {unit="birdnet_analysis.service", species=~"${bird:regex}"}
    | unpack
    | __error__=""
    | confidence > $threshold
    | species !~ "${exclude_species:pipe}"
    [$__interval]
  )
)

avg_over_time(
  {job="weather"}
  | json temperature_2m="temperature_2m"
  | unwrap temperature_2m
  [$__interval]
)

avg_over_time(
  {job="weather"}
  | json relative_humidity_2m="relative_humidity_2m"
  | unwrap relative_humidity_2m
  [$__interval]
)

sum by () (
  count_over_time(
    {unit="birdnet_analysis.service", species=~"${bird:regex}"}
    | unpack
| __error__=""
| confidence > $threshold
| species !~ "${exclude_species:pipe}"
    [$__interval]
  )
)

avg_over_time(
  {job="weather"}
  | json wind_speed_10m="wind_speed_10m"
  | unwrap wind_speed_10m
[$__interval]
)

avg_over_time(
  {job="weather"}
  | json pressure_msl="pressure_msl"
  | unwrap pressure_msl
[$__interval]
)

sum(
  count_over_time(
    {unit="birdnet_analysis.service", species=~".+"}
    | unpack
    | __error__=""
    | confidence > 0
    | species !~ "${exclude_species:pipe}"
    [$__auto]
  )
)

sum(
  count_over_time(
    {species="$bird"}
    | unpack
    | confidence > $threshold
    [$__range]
  )
)

max(
  max_over_time(
    {unit="birdnet_analysis.service"}
    | unpack
    | species="$bird"
    | confidence > $threshold
    | unwrap confidence
    [$__auto]
  )
)

sum(
  count_over_time(
    {unit="birdnet_analysis.service", species=~".+"}
    | unpack
    | __error__=""
    | confidence > $threshold
    | species !~ "${exclude_species:pipe}"
    [$__auto]
  )
)

count(
  sum by (species) (
    count_over_time(
      {unit="birdnet_analysis.service", species=~".+"}
      | unpack
      | __error__=""
      | confidence > $threshold
      | species !~ "${exclude_species:pipe}"
      [$__auto]
    )
  )
)

topk(
  8,
  sum by (species) (
    count_over_time(
      {unit="birdnet_analysis.service", species=~".+"}
      | unpack
      | __error__=""
      | species !~ "${exclude_species:pipe}"
      | confidence > $threshold
      [$__range]
    )
  )
)

sum(
  count_over_time(
    {unit="birdnet_analysis.service", species=~".+"}
    | unpack
    | confidence > $threshold
    | __error__=""
    | species !~ "${exclude_species:pipe}"
    [$__auto]
  )
)
